fn conditional_average(
    vals_1: &Vec<u64>,
    vals_2: &Vec<u64>,
    conds_1: &Vec<bool>,
    conds_2: &Vec<bool>,
    avgs: &mut Vec<u64>,
) {
    let n = vals_1.len();

    // Assume lengths are consistent as stated; keep debug checks for development.
    debug_assert_eq!(vals_2.len(), n);
    debug_assert_eq!(conds_1.len(), n);
    debug_assert_eq!(conds_2.len(), n);

    // Ensure output has the required length and can be overwritten.
    avgs.resize(n, 0);

    for i in 0..n {
        let c1 = conds_1[i];
        let c2 = conds_2[i];

        avgs[i] = match (c1, c2) {
            (true, true) => (vals_1[i] + vals_2[i]) / 2,
            (true, false) => vals_1[i],
            (false, true) => vals_2[i],
            (false, false) => unreachable!("Problem statement guarantees at least one condition is true"),
        };
    }
}